use verus::*;

verus! {

  // The function determines the winner given:
  // a: P1 (base points of participant 1)
  // b: T1 (time for participant 1)
  // c: P2 (base points of participant 2)
  // d: T2 (time for participant 2)
  //
  // Preconditions:
  // - P1 and P2 in [250, 3500], divisible by 250
  // - T1 and T2 in [0, 180]
  //
  // Final score S = max(3*P/10, P - P*T/250)
  // Return "Misha" if participant 1 wins, "Vasya" if participant 2 wins, or "Tie" if equal

  proof fn divisible_by_250(x: i64) -> bool {
    x % 250 == 0
  }

  fn final_score(P: i64, T: i64) -> i64
    requires
      250u64 <= P as u64 && P as u64 <= 3500u64 && divisible_by_250(P),
      0 <= T && T <= 180
  {
    let val1 = 3 * P / 10;
    let val2 = P - (P * T) / 250;
    if val1 > val2 { val1 } else { val2 }
  }

  #[verifier(external_body)]
  pub fn determine_winner(a: i8, b: i8, c: i8, d: i8) -> String
    requires
      // convert i8 to i64 to avoid overflow in arithmetic and to allow %250 operations:
      250 <= a as i64 && a as i64 <= 3500 && a as i64 % 250 == 0,
      0 <= b as i64 && b as i64 <= 180,
      250 <= c as i64 && c as i64 <= 3500 && c as i64 % 250 == 0,
      0 <= d as i64 && d as i64 <= 180,
    ensures
      // ensures that the returned string matches the comparison
      match_final_scores(a as i64, b as i64, c as i64, d as i64, &result)
  {
    // Use i64 for intermediate computation to avoid overflow and division issues
    let P1: i64 = a as i64;
    let T1: i64 = b as i64;
    let P2: i64 = c as i64;
    let T2: i64 = d as i64;

    let S1 = final_score(P1, T1);
    let S2 = final_score(P2, T2);

    if S1 > S2 {
      "Misha".to_string()
    } else if S2 > S1 {
      "Vasya".to_string()
    } else {
      "Tie".to_string()
    }
  }

  // Helper function to specify the correctness postcondition on the output string
  #[spec]
  fn match_final_scores(P1: i64, T1: i64, P2: i64, T2: i64, result: &String) -> bool {
    let S1 = final_score(P1, T1);
    let S2 = final_score(P2, T2);
    if S1 > S2 {
      *result == "Misha"
    } else if S2 > S1 {
      *result == "Vasya"
    } else {
      *result == "Tie"
    }
  }
}